// Command mellifera is the composition root: a flat, top-to-bottom constructor
// list that wires the whole app graph in one file. It reads configuration from
// the environment, opens the store, loads and starts the base-scanner (scanner)
// and tv-parser (metadata_source) plugin subprocesses, constructs enrich.Deps
// and wires it into the scan orchestrator, assembles the HTTP edge, and serves
// until SIGINT/SIGTERM. There is no DI container and no reflection wiring —
// every dependency is an explicit constructor call (ai-architecture §2 principle
// 5; mellifera-build skill; depguard denies reflect + DI frameworks).
//
// Dev-mode plugin loading: each plugin binary is loaded from a configurable
// filesystem path (env MELLIFERA_BASE_SCANNER / MELLIFERA_TV_PARSER, defaults
// bin/base-scanner / bin/tv-parser from `make build-plugin`). go:embed
// first-run extraction is deferred to release packaging (D11/Q20).
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"syscall"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// Launch-consent + identity constants shared with the plugin subprocess. The
// magic-cookie pair MUST match the values base-scanner AND tv-parser validate
// (MELLIFERA_MAGIC_COOKIE / mellifera-plugin-v1); a mismatch is a fatal
// substrate-handshake failure. coreVersion mirrors the plugins' min_core.
const (
	magicCookieKey   = "MELLIFERA_MAGIC_COOKIE"
	magicCookieValue = "mellifera-plugin-v1"
	coreVersion      = "0.1.0"
	scannerService   = "mellifera.scanner.v1.Scanner"
	metadataService  = "mellifera.metadata.v1.MetadataSource"
)

// Lifecycle timeouts: a bounded read-header window (slowloris protection) and a
// best-effort graceful-shutdown budget. The plugin subprocess has its own
// SIGTERM grace (plugin.Manager.Stop), independent of this budget.
const (
	readHeaderTimeout = 10 * time.Second
	shutdownTimeout   = 15 * time.Second
)

func main() {
	cfg := loadConfig()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// --- wiring: flat constructor list, the whole app graph in order ---
	st, err := store.Open(ctx, cfg.dsn)
	fatalOn(err, "open store")
	defer st.Close()

	reg, err := module.Open(ctx, st)
	fatalOn(err, "open module registry")

	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   magicCookieKey,
		MagicCookieValue: magicCookieValue,
		CoreVersion:      coreVersion,
	})
	fatalOn(mgr.Load("base-scanner", cfg.baseScannerPath, []sdk.Capability{
		{Type: "scanner", ID: "default", ProtoService: scannerService},
	}), "load base-scanner")
	fatalOn(mgr.Start(ctx, "base-scanner"), "start base-scanner")

	// tv-parser is the first metadata_source plugin (parseTV extracted from
	// base-scanner in T06/T07). It loads from a filesystem path with the same
	// dev-mode pattern + cookie pair as base-scanner; its capability declaration
	// matches the plugin's Handshake (T06).
	fatalOn(mgr.Load("tv-parser", cfg.tvParserPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	}), "load tv-parser")
	fatalOn(mgr.Start(ctx, "tv-parser"), "start tv-parser")

	scanDeps := scan.Deps{
		Store:   st,
		Modules: reg,
		Plugins: mgr,
		Enrich:  enrich.Deps{Store: st, Modules: reg, Plugins: mgr},
	}
	// Async enrich queue (arch §4.4): a bounded worker pool that derives pending
	// (item, plugin) work from items + the ledger and drains it for the process
	// lifetime. Constructed + started BEFORE the server serves so the first
	// scan's Notify lands in a running pool (INV-start-before-serve). Flat
	// constructor call — no DI, no reflect (INV-flat-wiring).
	enrichQueue := enrich.NewQueue(scanDeps.Enrich, cfg.enrich)
	fatalOn(enrichQueue.Start(ctx), "start enrich queue")
	// scan hands the library to the queue after persisting items pending. The
	// closure substitutes the PROCESS ctx (not the per-request scan ctx) so the
	// queue's derive/feeder outlives the HTTP request — otherwise the feeder
	// would abort the moment the scan handler returns and never drain
	// (INV-context-shared: SIGINT/SIGTERM cancels pool + server together).
	scanDeps.Notify = func(_ context.Context, libraryID int64) {
		enrichQueue.Notify(ctx, libraryID)
	}
	handler := api.New(api.Deps{
		AdminToken: cfg.adminToken,
		Store:      st,
		Scan: func(ctx context.Context, libraryID int64) (scan.Result, error) {
			return scan.Run(ctx, scanDeps, libraryID)
		},
	})

	srv := &http.Server{
		Addr:              cfg.listenAddr,
		Handler:           handler,
		ReadHeaderTimeout: readHeaderTimeout,
	}

	serveErr := make(chan error, 1)
	go func() { serveErr <- srv.ListenAndServe() }()

	select {
	case <-ctx.Done():
		slog.Info("shutting down (signal received)")
	case err := <-serveErr:
		if !errors.Is(err, http.ErrServerClosed) {
			fatalOn(err, "http server") // unexpected early exit; store.Close runs via defer
		}
		return // server already closed cleanly
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	logErr(srv.Shutdown(shutdownCtx), "shutdown http server")
	// INV-shutdown-order: stop accepting HTTP, THEN stop the enrich pool, THEN
	// stop plugin subprocesses. The pool stops before the plugin manager so
	// in-flight RPCs can drain against still-live subprocesses (best-effort
	// within shutdownTimeout). Stop is void: it cancels workers + waits.
	enrichQueue.Stop()
	logErr(mgr.Stop(shutdownCtx, "base-scanner"), "stop base-scanner")
	logErr(mgr.Stop(shutdownCtx, "tv-parser"), "stop tv-parser")
	// store.Close runs via the deferred st.Close() in main.
}

// config is the resolved startup configuration read from the environment.
type config struct {
	dsn             string
	adminToken      string
	baseScannerPath string
	tvParserPath    string
	listenAddr      string
	enrich          enrich.QueueConfig
}

// loadConfig reads configuration from the environment with sane MVP defaults.
// It fail-fast aborts on the one hard requirement (an admin token) and ensures
// the data directory exists so the store can open its SQLite file underneath.
func loadConfig() config {
	dataDir := envOr("MELLIFERA_DATA_DIR", "./data")
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		fatal("create data dir", err)
	}
	adminToken := os.Getenv("MELLIFERA_ADMIN_TOKEN")
	if adminToken == "" {
		slog.Error("MELLIFERA_ADMIN_TOKEN is required; refusing to serve with an empty admin token")
		os.Exit(1)
	}
	return config{
		dsn:             filepath.Join(dataDir, "mellifera.db"),
		adminToken:      adminToken,
		baseScannerPath: envOr("MELLIFERA_BASE_SCANNER", "bin/base-scanner"),
		tvParserPath:    envOr("MELLIFERA_TV_PARSER", "bin/tv-parser"),
		listenAddr:      envOr("MELLIFERA_LISTEN", "127.0.0.1:8080"),
		// Async enrich queue knobs (arch §4.4). Every field has a §4.4 default;
		// a missing/empty/malformed value falls back to it + logs a warning
		// (INV-env-defaults: startup never aborts on an enrich knob). Only the
		// admin token remains fail-fast.
		enrich: enrich.QueueConfig{
			Workers:       envInt("MELLIFERA_ENRICH_WORKERS", 4),
			MaxAttempts:   envInt("MELLIFERA_ENRICH_MAX_ATTEMPTS", 3),
			LeaseTTL:      envDuration("MELLIFERA_ENRICH_LEASE_TTL", 60*time.Second),
			Backoff:       envDuration("MELLIFERA_ENRICH_BACKOFF", 2*time.Second),
			ExhaustedCool: envDuration("MELLIFERA_ENRICH_EXHAUSTED_COOL", 7*24*time.Hour),
			NoDataCool:    envDuration("MELLIFERA_ENRICH_NODATA_COOL", 30*24*time.Hour),
			CoolCap:       envDuration("MELLIFERA_ENRICH_COOL_CAP", 365*24*time.Hour),
		},
	}
}

// envInt reads an integer env var, falling back to def (and logging a warning)
// when it is unset/empty/malformed. Used for the enrich knobs (INV-env-defaults).
func envInt(key string, def int) int {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		slog.Warn("invalid int env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return n
}

// envDuration reads a duration env var (time.ParseDuration syntax), falling back
// to def (and logging a warning) when unset/empty/malformed (INV-env-defaults).
func envDuration(key string, def time.Duration) time.Duration {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	d, err := time.ParseDuration(v)
	if err != nil {
		slog.Warn("invalid duration env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return d
}

// envOr returns the named env var or def when it is unset/empty.
func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// fatalOn aborts the process if err is non-nil. Used for startup wiring, where a
// failure means the app cannot run.
func fatalOn(err error, label string) {
	if err != nil {
		fatal(label, err)
	}
}

func fatal(label string, err error) {
	slog.Error(label, "error", err)
	os.Exit(1)
}

// logErr logs a non-nil error without aborting. Used in the graceful-shutdown
// path so each step gets a chance to run even if an earlier one errored.
func logErr(err error, label string) {
	if err != nil {
		slog.Error(label, "error", err)
	}
}
